def update_ch(ch_num, data_dict):
    fpath = f'work/data/senior3/chapter{ch_num:02d}.json'
    d = json.load(open(fpath, encoding='utf-8'))
    for q in d['questions']:
        qid = q['id']
        if qid in data_dict:
            item = data_dict[qid]
            q['question'] = item['q']
            q['options'] = item['opts']
            q['answer'] = item['ans']
    with open(fpath, 'w', encoding='utf-8') as f:
        json.dump(d, f, ensure_ascii=False, indent=2)
    print(f"Senior 3 Chapter {ch_num:02d} completely updated and lean-rewritten!")

if __name__ == '__main__':
    update_ch(1, CH01_DATA)
    update_ch(2, CH02_DATA)
    update_ch(3, CH03_DATA)
    update_ch(4, CH04_DATA)

